package main

import (
	"encoding/json"
	"context"
	"os/signal"
	"syscall"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"

	co "github.com/makeacalendar/make-a-calendar-calendarops/internal/calendarops"
	"github.com/makeacalendar/make-a-calendar-calendarops/internal/webassets"
)

type server struct { requests atomic.Uint64; exports atomic.Uint64; errors atomic.Uint64 }
type statusWriter struct { http.ResponseWriter; status int }
func (w *statusWriter) WriteHeader(code int){w.status=code;w.ResponseWriter.WriteHeader(code)}
func (w *statusWriter) Write(p []byte)(int,error){if w.status==0{w.status=http.StatusOK};return w.ResponseWriter.Write(p)}
type apiError struct { Error string `json:"error"` }
func writeJSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json; charset=utf-8");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func bad(w http.ResponseWriter,msg string){writeJSON(w,http.StatusBadRequest,apiError{msg})}
func parseYearMonth(r *http.Request)(int,int,error){p:=strings.Split(strings.Trim(r.URL.Path,"/"),"/");if len(p)<4{return 0,0,fmt.Errorf("expected year and month path segments")};y,e:=strconv.Atoi(p[len(p)-2]);if e!=nil||y<1||y>9998{return 0,0,fmt.Errorf("year must be 1..9998")};m,e:=strconv.Atoi(p[len(p)-1]);if e!=nil||m<1||m>12{return 0,0,fmt.Errorf("month must be 1..12")};return y,m,nil}
func (s *server) routes() http.Handler {defaultWeek:=os.Getenv("CALENDAR_WEEK_START");if defaultWeek!="sunday"{defaultWeek="monday"};defaultYear:=2027;if y,e:=strconv.Atoi(os.Getenv("CALENDAR_DEFAULT_YEAR"));e==nil&&y>=1&&y<=9998{defaultYear=y};mux:=http.NewServeMux();mux.HandleFunc("GET /healthz",func(w http.ResponseWriter,r *http.Request){w.WriteHeader(200);_,_=w.Write([]byte("ok\n"))});mux.HandleFunc("GET /readyz",func(w http.ResponseWriter,r *http.Request){w.WriteHeader(200);_,_=w.Write([]byte("ready\n"))});mux.HandleFunc("GET /metrics",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/plain; version=0.0.4");fmt.Fprintf(w,"# TYPE calendarops_http_requests_total counter\ncalendarops_http_requests_total %d\n# TYPE calendarops_exports_total counter\ncalendarops_exports_total %d\n# TYPE calendarops_http_errors_total counter\ncalendarops_http_errors_total %d\n",s.requests.Load(),s.exports.Load(),s.errors.Load())})
	mux.HandleFunc("GET /",func(w http.ResponseWriter,r *http.Request){if r.URL.Path=="/"{b,e:=webassets.Files.ReadFile("index.html");if e!=nil{http.Error(w,"interface unavailable",500);return};page:=strings.ReplaceAll(string(b),"{{DEFAULT_YEAR}}",strconv.Itoa(defaultYear));page=strings.ReplaceAll(page,"{{WEEK_START}}",defaultWeek);w.Header().Set("Content-Type","text/html; charset=utf-8");_,_=w.Write([]byte(page));return};if r.URL.Path=="/openapi.yaml"{b,e:=webassets.Files.ReadFile("openapi.yaml");if e!=nil{http.Error(w,"specification unavailable",500);return};w.Header().Set("Content-Type","application/yaml");_,_=w.Write(b);return};http.NotFound(w,r)})
	mux.HandleFunc("GET /v1/calendar/month/{year}/{month}",func(w http.ResponseWriter,r *http.Request){y,m,e:=parseYearMonth(r);if e!=nil{bad(w,e.Error());return};ws:=r.URL.Query().Get("weekStart");if ws==""{ws=defaultWeek};g,e:=co.MonthGrid(y,m,ws,false);if e!=nil{bad(w,e.Error());return};writeJSON(w,200,g)})
	mux.HandleFunc("GET /v1/calendar/year/{year}",func(w http.ResponseWriter,r *http.Request){y,e:=strconv.Atoi(r.PathValue("year"));if e!=nil||y<1||y>9998{bad(w,"year must be 1..9998");return};ws:=r.URL.Query().Get("weekStart");if ws==""{ws=defaultWeek};v,e:=co.YearMonths(y,ws);if e!=nil{bad(w,e.Error());return};writeJSON(w,200,map[string]any{"year":y,"months":v})})
	mux.HandleFunc("GET /v1/holidays/us/{year}",func(w http.ResponseWriter,r *http.Request){y,e:=strconv.Atoi(r.PathValue("year"));if e!=nil||y<2021||y>9998{bad(w,"holiday year must be 2021..9998");return};writeJSON(w,200,co.USFederalHolidays(y))})
	mux.HandleFunc("GET /v1/business-days",func(w http.ResponseWriter,r *http.Request){a,e:=co.ParseDate(r.URL.Query().Get("start"));if e!=nil{bad(w,"start must be YYYY-MM-DD");return};b,e:=co.ParseDate(r.URL.Query().Get("end"));if e!=nil{bad(w,"end must be YYYY-MM-DD");return};if a.Year<2021||b.Year>9998||b.Before(a)||a.DaysUntil(b)>3660{bad(w,"range must be ordered, within 2021..9998, and at most ten years");return};opts:=co.DefaultBusinessOptions();opts.Excluded=co.HolidaySetBetween(a,b);includeStart:=r.URL.Query().Get("includeStart")=="true";includeEnd:=r.URL.Query().Get("includeEnd")!="false";n,e:=co.CountBusinessDays(a,b,includeStart,includeEnd,opts);if e!=nil{bad(w,e.Error());return};writeJSON(w,200,map[string]any{"start":a,"end":b,"count":n,"includeStart":includeStart,"includeEnd":includeEnd,"excludes":"US federal observed holidays"})})
	mux.HandleFunc("GET /v1/business-days/add",func(w http.ResponseWriter,r *http.Request){a,e:=co.ParseDate(r.URL.Query().Get("date"));if e!=nil{bad(w,"date must be YYYY-MM-DD");return};n,e:=strconv.Atoi(r.URL.Query().Get("days"));if e!=nil||n<0||n>10000||a.Year<2021{bad(w,"date must be 2021..9998 and days an integer from 0 to 10000");return};direction:=r.URL.Query().Get("direction");if direction==""{direction="next"};if direction!="next"&&direction!="previous"{bad(w,"direction must be next or previous");return};opts:=co.DefaultBusinessOptions();if direction=="next"{opts.Excluded=co.HolidaySetBetween(a,a.AddDays(n*2+30))}else{opts.Excluded=co.HolidaySetBetween(a.AddDays(-n*2-30),a)};var d co.Date;if direction=="previous"{d,e=co.SubtractBusinessDays(a,n,opts)}else{d,e=co.AddBusinessDays(a,n,opts)};if e!=nil||d.Year<2021||d.Year>9998{bad(w,"result is outside supported federal-holiday coverage (2021..9998)");return};writeJSON(w,200,map[string]any{"date":a,"businessDays":n,"result":d})})
	mux.HandleFunc("GET /v1/pay-periods",func(w http.ResponseWriter,r *http.Request){a,e:=co.ParseDate(r.URL.Query().Get("start"));if e!=nil{bad(w,"start must be YYYY-MM-DD");return};b,e:=co.ParseDate(r.URL.Query().Get("end"));if e!=nil{bad(w,"end must be YYYY-MM-DD");return};anchor,e:=co.ParseDate(r.URL.Query().Get("anchor"));if e!=nil{bad(w,"anchor must be YYYY-MM-DD");return};if a.Year<2021||b.Year>9998||anchor.Year<2021||a.DaysUntil(b)>3660{bad(w,"range is limited to 10 years");return};opts:=co.DefaultBusinessOptions();lo:=a;if anchor.Before(lo){lo=anchor};hi:=b;if hi.Before(anchor){hi=anchor};opts.Excluded=co.HolidaySetBetween(lo,hi);adjust:=r.URL.Query().Get("adjust");if adjust==""{adjust="next"};if adjust!="next"&&adjust!="previous"{bad(w,"adjust must be next or previous");return};v,e:=co.PayDates(a,b,anchor,r.URL.Query().Get("cadence"),adjust,opts);if e!=nil{bad(w,e.Error());return};writeJSON(w,200,v)})
	mux.HandleFunc("GET /v1/shift-schedule",func(w http.ResponseWriter,r *http.Request){a,e:=co.ParseDate(r.URL.Query().Get("start"));if e!=nil{bad(w,"start must be YYYY-MM-DD");return};b,e:=co.ParseDate(r.URL.Query().Get("end"));if e!=nil{bad(w,"end must be YYYY-MM-DD");return};if b.Before(a)||a.DaysUntil(b)>366{bad(w,"range must be ordered and at most 366 days");return};anchor,e:=co.ParseDate(r.URL.Query().Get("anchor"));if e!=nil{bad(w,"anchor must be YYYY-MM-DD");return};cycle,e:=co.NamedShift(r.URL.Query().Get("cycle"));if e!=nil{bad(w,e.Error());return};type duty struct{Date co.Date `json:"date"`; OnDuty bool `json:"onDuty"`};var days []duty;for d:=a;!b.Before(d);d=d.AddDays(1){on,_:=co.ShiftOn(d,anchor,cycle);days=append(days,duty{d,on})};writeJSON(w,200,map[string]any{"cycle":r.URL.Query().Get("cycle"),"anchor":anchor,"days":days,"notice":"Duty-date visualization only; not legal working-hour compliance advice."})})
	mux.HandleFunc("GET /v1/fiscal/{pattern}",func(w http.ResponseWriter,r *http.Request){y,e:=strconv.Atoi(r.URL.Query().Get("year"));if e!=nil||y<2021||y>9997{bad(w,"fiscal year must be 2021..9997");return};v,e:=co.RetailPeriods(y,r.PathValue("pattern"));if e!=nil{bad(w,e.Error());return};writeJSON(w,200,map[string]any{"anchoring":"Sunday nearest February 1 (NRF-style)","periods":v})})
	mux.HandleFunc("GET /v1/exports/month.svg/{year}/{month}",func(w http.ResponseWriter,r *http.Request){y,e:=strconv.Atoi(r.PathValue("year"));if e!=nil{bad(w,"year must be an integer");return};m,e:=strconv.Atoi(r.PathValue("month"));if e!=nil{bad(w,"month must be an integer");return};ws:=r.URL.Query().Get("weekStart");if ws==""{ws=defaultWeek};g,e:=co.MonthGrid(y,m,ws,false);if e!=nil{bad(w,e.Error());return};hols:=map[co.Date]string{};if r.URL.Query().Get("holidays")!="false"{hols=co.HolidaySetBetween(co.Date{Year:y,Month:m,Day:1},co.Date{Year:y,Month:m,Day:co.DaysInMonth(y,m)})};s.exports.Add(1);w.Header().Set("Content-Type","image/svg+xml");_,_=w.Write([]byte(co.RenderMonthSVG(g,hols)))})
	mux.HandleFunc("GET /v1/exports/holidays.ics",func(w http.ResponseWriter,r *http.Request){y,e:=strconv.Atoi(r.URL.Query().Get("year"));if e!=nil||y<2021||y>9998{bad(w,"holiday year must be 2021..9998");return};s.exports.Add(1);w.Header().Set("Content-Type","text/calendar; charset=utf-8");w.Header().Set("Content-Disposition","attachment; filename=us-holidays.ics");_,_=w.Write([]byte(co.ICSHolidayEvents(co.USFederalHolidays(y))))})
	return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){s.requests.Add(1);start:=time.Now();sw:=&statusWriter{ResponseWriter:w};mux.ServeHTTP(sw,r);if sw.status>=400{s.errors.Add(1)};slog.Info("http request","method",r.Method,"path",r.URL.Path,"status",sw.status,"duration_ms",time.Since(start).Milliseconds())})}
func main(){slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout,nil)));addr:=os.Getenv("ADDR");if addr==""{addr=":8080"};s:=&server{};srv:=&http.Server{Addr:addr,Handler:s.routes(),ReadHeaderTimeout:5*time.Second};done:=make(chan os.Signal,1);signal.Notify(done,os.Interrupt,syscall.SIGTERM);go func(){<-done;ctx,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();_ = srv.Shutdown(ctx)}();slog.Info("calendarops server starting","addr",addr);if e:=srv.ListenAndServe();e!=nil&&e!=http.ErrServerClosed{slog.Error("server stopped","error",e);os.Exit(1)}}
